   */
  async recordRun(run: Omit<Run, 'id'>): Promise<Run> {
    const id = this.#ulid();
    await this.#db
      .prepare(
        `INSERT INTO runs (id, source_module, started_at, finished_at, fetched, cached, utterances, unattributed, failures)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .bind(
