cat > dev/requirements/logic/cases/operations-credential.8.3.case.ts <<'EOF'
import assert from 'node:assert/strict';
import type { Case } from '../../registry.ts';
import { admit } from '../../../../src/backend/api/operations.ts';
import type { Env } from '../../../../src/backend/env.ts';

const TOKEN = 'a-long-enough-operator-token';
const configured = { DASHBOARD_TOKEN: TOKEN } as Env;
const asking = (authorization?: string) =>
  new Request('https://hitbut.test/api/v1/operations', { headers: authorization ? { authorization } : {} });

export default {
  title: 'the operations credential admits the configured token and nothing else',
  run() {
    assert.equal(admit(asking(`Bearer ${TOKEN}`), configured).admitted, true);

    const refused = (authorization?: string) => {
      const admission = admit(asking(authorization), configured);
      assert.equal(admission.admitted, false, `${authorization ?? '(no header)'} was admitted`);
      if (!admission.admitted) assert.equal(admission.status, 401);
    };

    refused();
    refused('Bearer');
    refused(`Bearer ${TOKEN}x`);
    // One character out, right length: the comparison must not pass on a prefix, and must
    // not answer faster for a token that is nearly right.
    refused(`Bearer ${TOKEN.slice(0, -1)}X`);
    // The right secret in the wrong scheme is not a credential.
    refused(TOKEN);
    refused(`Basic ${TOKEN}`);
  },
} satisfies Case<void>;
EOF
cat > dev/requirements/logic/cases/module-runs.8.5.case.ts <<'EOF'
import assert from 'node:assert/strict';
import type { Case } from '../../registry.ts';
import { operationsView } from '../../../../src/backend/api/operations.ts';
import { SourceRegistry } from '../../../../src/backend/acquisition/registry.ts';
import { emptyCorpus, fixtureSource, REFERENCE_NOW } from '../../shared/fixtures.ts';

export default {
  title: 'operations reports what each module fetched, cached and failed on',
  async run() {
    const corpus = emptyCorpus();
    const registry = new SourceRegistry();
    registry.register(fixtureSource({ documents: [] }));
    const [module] = registry.all();

    await corpus.recordRun({
      sourceModule: module.id,
      startedAt: REFERENCE_NOW,
      finishedAt: REFERENCE_NOW,
      fetched: 4,
      cached: 11,
      utterances: 9,
      unattributed: 2,
      failures: [
        { key: 'protocol-2026-03-04', reason: 'bot_wall: the response was a challenge page' },
        { key: '01JB', reason: 'no embedding model is bound' },
      ],
    });

    const view = await operationsView(corpus, registry, () => REFERENCE_NOW);
    assert.equal(view.modules.length, 1);
    const [state] = view.modules;
    assert.equal(state.id, module.id);
    assert.equal(state.publisher, module.publisher);
    assert.ok(state.lastRun, 'a module that has run must carry its run');

    assert.equal(state.lastRun.fetched, 4);
    assert.equal(state.lastRun.cached, 11);
    assert.equal(state.lastRun.utterances, 9);
    // Both kinds of failure survive the round trip, and each keeps the key it was about —
    // "something failed" is not a report anybody can act on.
    assert.deepEqual(
      state.lastRun.failures.map((failure) => failure.key),
      ['protocol-2026-03-04', '01JB'],
    );
    assert.match(state.lastRun.failures[0].reason, /bot_wall/);
    assert.match(state.lastRun.failures[1].reason, /embedding model/);
  },
} satisfies Case<void>;
EOF
cat > dev/requirements/logic/cases/never-run.8.6.case.ts <<'EOF'
import assert from 'node:assert/strict';
import type { Case } from '../../registry.ts';
import { operationsView } from '../../../../src/backend/api/operations.ts';
import { SourceRegistry } from '../../../../src/backend/acquisition/registry.ts';
import { emptyCorpus, fixtureSource, REFERENCE_NOW } from '../../shared/fixtures.ts';

// The distinction the dashboard exists for. A module whose parser broke on the first
// document and a module nobody ever wired up both show zero utterances, and only one of
// them is a problem — so never-run must not be spelled as a run that found nothing.
export default {
  title: 'a module that has never run is never reported as having run and found nothing',
  async run() {
    const corpus = emptyCorpus();
    const registry = new SourceRegistry();
    registry.register(fixtureSource({ documents: [], id: 'has-run' }));
    registry.register(fixtureSource({ documents: [], id: 'never-run' }));

    await corpus.recordRun({
      sourceModule: 'has-run',
      startedAt: REFERENCE_NOW,
      finishedAt: REFERENCE_NOW,
      // A real zero: it ran, and there was nothing new. This is the row the other module
      // must not be made to look like.
      fetched: 0,
      cached: 0,
      utterances: 0,
      unattributed: 0,
      failures: [],
    });

    const view = await operationsView(corpus, registry, () => REFERENCE_NOW);
    const byId = new Map(view.modules.map((module) => [module.id, module]));

    // Both modules are listed: the view is driven by the registry, so a module with no
    // rows is visible rather than absent — absent would be indistinguishable from healthy.
    assert.deepEqual([...byId.keys()].sort(), ['has-run', 'never-run']);

    assert.equal(byId.get('never-run')?.lastRun, null, 'never-run must be null, not a zeroed run');
    const ran = byId.get('has-run')?.lastRun;
    assert.ok(ran, 'the module that ran must carry its run');
    assert.equal(ran.utterances, 0, 'and its zero must stay a zero');
  },
} satisfies Case<void>;
EOF
