// The dashboard's marks, drawn as inline SVG rather than pulled from a charting library:
// three small forms do not justify a dependency, and nothing here loads from a CDN.
//
// Form follows the data's job. Headline counts are stat tiles, not a one-bar chart.
// Venue is magnitude across long-named classes, so horizontal bars. Year is magnitude
// over time, so columns. Length carries the magnitude, which leaves colour with one job
// and one hue.
import type { Distribution } from '../../shared/types.ts';

const BAR = 22;
const GAP = 8;

/** A count, formatted for a reader rather than for a machine. */
export const count = (value: number): string => value.toLocaleString('en-GB');

export function StatTile({ label, value, note }: { label: string; value: number; note?: string }): JSX.Element {
  return (
    <div class="tile">
      <div class="tile__value">{count(value)}</div>
      <div class="tile__label">{label}</div>
      {note ? <div class="tile__note">{note}</div> : null}
    </div>
  );
}

/**
 * Horizontal bars, because a venue's name is a phrase and a rotated axis label is a
 * readability tax nobody has to pay. Sorted by magnitude, which is the comparison.
 */
export function VenueBars({ distribution }: { distribution: Distribution }): JSX.Element {
  const rows = distribution.buckets;
  const most = Math.max(1, ...rows.map((row) => row.count));
  const height = rows.length * (BAR + GAP);

  return (
    <svg class="chart" viewBox={`0 0 320 ${height}`} width="100%" height={height} role="img"
         aria-label="utterances by venue">
      {rows.map((row, index) => {
        const y = index * (BAR + GAP);
        const width = Math.max(2, (row.count / most) * 190);
        return (
          <g key={row.name}>
            <text class="chart__name" x="0" y={y + BAR - 6}>{row.name}</text>
            {/* 4px rounded data-end, anchored at the baseline so the bar starts square. */}
            <rect class="chart__bar" x="124" y={y} width={width} height={BAR} rx="4" />
            <text class="chart__value" x={124 + width + 8} y={y + BAR - 6}>{count(row.count)}</text>
          </g>
        );
      })}
    </svg>
  );
}

/**
 * Columns over time. The undated are deliberately NOT a column here: they have no year to
 * stand at, and giving them one would put back the guess `1.3` refused to make. They are
 * reported beside the axis instead, as their own figure.
 */
export function YearColumns({ distribution }: { distribution: Distribution }): JSX.Element {
  const rows = distribution.buckets;
  const most = Math.max(1, ...rows.map((row) => row.count));
  const width = Math.max(1, rows.length) * 44;

  return (
    <div class="years">
      <svg class="chart" viewBox={`0 0 ${width} 150`} width="100%" height="150" role="img"
           aria-label="utterances by year">
        {rows.map((row, index) => {
          const columnHeight = Math.max(2, (row.count / most) * 104);
          const x = index * 44 + 6;
          return (
            <g key={row.name}>
              <text class="chart__value" x={x + 16} y={126 - columnHeight - 6} text-anchor="middle">{count(row.count)}</text>
              <rect class="chart__bar" x={x} y={126 - columnHeight} width="32" height={columnHeight} rx="4" />
              <text class="chart__name" x={x + 16} y="144" text-anchor="middle">{row.name}</text>
            </g>
          );
        })}
        <line class="chart__axis" x1="0" y1="126" x2={width} y2="126" />
      </svg>
      <p class="years__undated">
        <strong>{count(distribution.undated)}</strong> undated — no source established when these were said,
        so they stand outside the axis rather than inside a year nobody claimed.
      </p>
    </div>
  );
}
